const raw = $node['OpenAI Extract'].json.message?.content || '';

// Strip markdown fences
const clean = raw.replace(/^```[a-z]*\n?/gm, '').replace(/```\s*$/gm, '').trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch(e) {
  const match = clean.match(/\{[\s\S]*\}/);
  if (!match) return [{ json: {
    reply: "Sorry, I had a hiccup! Where would you like to go?",
    status: 'collecting', tripData: {}
  }}];
  try { parsed = JSON.parse(match[0]); }
  catch { return [{ json: {
    reply: "Sorry, I had a hiccup! Where would you like to go?",
    status: 'collecting', tripData: {}
  }}]; }
}

const reply     = (parsed.reply   || '').trim();
const status    = parsed.status   || 'collecting';
const extracted = parsed.extracted || {};

// Sanitise — only keep non-empty strings
const tripData = {};
Object.entries(extracted).forEach(([k, v]) => {
  const val = String(v || '').trim();
  if (val) tripData[k] = val;
});

// Validate tripType
const VALID_TYPES = ['Tropical Resort', 'Cruise Adventure', 'Airbnb Getaway', 'Adventure Trip'];
if (tripData.tripType && !VALID_TYPES.includes(tripData.tripType)) {
  delete tripData.tripType;
}

// Validate accommodationType  
const VALID_ACCOM = ['Hotel', 'Boutique Hotel', 'Entire Home / Airbnb', 'Apartment', 'Hostel', 'No preference'];
if (tripData.accommodationType && !VALID_ACCOM.includes(tripData.accommodationType)) {
  // Try to normalise it
  const raw_a = tripData.accommodationType.toLowerCase();
  if (raw_a.includes('hotel') && raw_a.includes('boutique')) tripData.accommodationType = 'Boutique Hotel';
  else if (raw_a.includes('hotel'))   tripData.accommodationType = 'Hotel';
  else if (raw_a.includes('airbnb') || raw_a.includes('home') || raw_a.includes('villa')) tripData.accommodationType = 'Entire Home / Airbnb';
  else if (raw_a.includes('apart'))   tripData.accommodationType = 'Apartment';
  else if (raw_a.includes('hostel'))  tripData.accommodationType = 'Hostel';
  else delete tripData.accommodationType;
}

// Validate status
const VALID_STATUS = ['collecting', 'clarifying', 'ready'];
const safeStatus = VALID_STATUS.includes(status) ? status : 'collecting';

return [{ json: { reply, status: safeStatus, tripData } }];
